-- =====================================================================
-- Estados sin impuesto a los sueldos (FL, NH, NV, SD, TN, TX, WA, WY), fecha límite de Utah
-- y regla de fin de semana / feriado del 1040-NR. Verificado 2026-10-30. Generado por scripts/state-no-wage-tax.py.
-- Alaska: pendiente (sin página oficial explícita).
-- =====================================================================

insert into public.tax_rules (key, value, year, jurisdiction, source_url, verified_at, reviewed_by, notes) values
  ('state_return_nonresident', '{"no_wage_tax": true, "agency": "the Florida Department of Revenue", "quote": "Florida does not impose a personal income tax, so there are no filing requirements.", "summary": {"es": "Según el Florida Department of Revenue, el estado no cobra impuesto a los sueldos, así que por tu sueldo ahí no tendrías declaración estatal. Confírmalo en la fuente.", "en": "According to the Florida Department of Revenue, the state doesn’t tax wages, so you wouldn’t have a state return for your wages there. Confirm it at the source."}}'::jsonb, 2026, 'FL', 'https://floridarevenue.com/faq/Pages/FAQDetails.aspx?FAQID=1466', '2026-10-30', 'pendiente Enrolled Agent', 'Cita textual: "Florida does not impose a personal income tax, so there are no filing requirements."'),
  ('state_return_nonresident', '{"no_wage_tax": true, "agency": "the New Hampshire Department of Revenue Administration", "quote": "The State of New Hampshire does not have an income tax on an individual''s reported W-2 wages.", "summary": {"es": "Según el New Hampshire Department of Revenue Administration, el estado no cobra impuesto a los sueldos, así que por tu sueldo ahí no tendrías declaración estatal. Confírmalo en la fuente.", "en": "According to the New Hampshire Department of Revenue Administration, the state doesn’t tax wages, so you wouldn’t have a state return for your wages there. Confirm it at the source."}}'::jsonb, 2026, 'NH', 'https://www.revenue.nh.gov/taxes-glance/interest-dividends-tax', '2026-10-30', 'pendiente Enrolled Agent', 'Cita textual: "The State of New Hampshire does not have an income tax on an individual''s reported W-2 wages."'),
  ('state_return_nonresident', '{"no_wage_tax": true, "agency": "the Nevada Department of Taxation", "quote": "While Nevada does not have an individual income tax, it does levy other types of taxes, such as sales tax and property tax.", "summary": {"es": "Según el Nevada Department of Taxation, el estado no cobra impuesto a los sueldos, así que por tu sueldo ahí no tendrías declaración estatal. Confírmalo en la fuente.", "en": "According to the Nevada Department of Taxation, the state doesn’t tax wages, so you wouldn’t have a state return for your wages there. Confirm it at the source."}}'::jsonb, 2026, 'NV', 'https://tax.nv.gov/about-nevada-department-of-taxation/income-tax-in-nevada/', '2026-10-30', 'pendiente Enrolled Agent', 'Cita textual: "While Nevada does not have an individual income tax, it does levy other types of taxes, such as sales tax and property tax."'),
  ('state_return_nonresident', '{"no_wage_tax": true, "agency": "the South Dakota Department of Revenue", "quote": "South Dakota is one of seven states that does not impose a state income tax.", "summary": {"es": "Según el South Dakota Department of Revenue, el estado no cobra impuesto a los sueldos, así que por tu sueldo ahí no tendrías declaración estatal. Confírmalo en la fuente.", "en": "According to the South Dakota Department of Revenue, the state doesn’t tax wages, so you wouldn’t have a state return for your wages there. Confirm it at the source."}}'::jsonb, 2026, 'SD', 'https://dor.sd.gov/individuals/taxes/', '2026-10-30', 'pendiente Enrolled Agent', 'Cita textual: "South Dakota is one of seven states that does not impose a state income tax."'),
  ('state_return_nonresident', '{"no_wage_tax": true, "agency": "the Tennessee Department of Revenue", "quote": "The tax is fully repealed beginning January 1, 2021.", "summary": {"es": "Según el Tennessee Department of Revenue, el estado no cobra impuesto a los sueldos, así que por tu sueldo ahí no tendrías declaración estatal. El único impuesto a la renta que tenía (Hall, sobre intereses y dividendos) se eliminó desde 2021. Confírmalo en la fuente.", "en": "According to the Tennessee Department of Revenue, the state doesn’t tax wages, so you wouldn’t have a state return for your wages there. Its only income tax (Hall, on interest and dividends) was repealed starting in 2021. Confirm it at the source."}}'::jsonb, 2026, 'TN', 'https://revenue.support.tn.gov/hc/en-us/articles/360057828631-HIT-3-Hall-Income-Tax-Repealed-Beginning-January-1-2021', '2026-10-30', 'pendiente Enrolled Agent', 'Cita textual: "The tax is fully repealed beginning January 1, 2021."'),
  ('state_return_nonresident', '{"no_wage_tax": true, "agency": "the Texas Economic Development Corporation (partner of the Texas Governor’s office)", "quote": "With no corporate or personal income tax, Texas has one of the lowest tax burdens in the nation.", "summary": {"es": "Según la Texas Economic Development Corporation (socia de la oficina del gobernador de Texas), el estado no cobra impuesto a los sueldos, así que por tu sueldo ahí no tendrías declaración estatal. Confírmalo en la fuente.", "en": "According to the Texas Economic Development Corporation (partner of the Texas Governor’s office), the state doesn’t tax wages, so you wouldn’t have a state return for your wages there. Confirm it at the source."}}'::jsonb, 2026, 'TX', 'https://businessintexas.com/why-texas/taxes-incentives/taxes/', '2026-10-30', 'pendiente Enrolled Agent', 'Cita textual: "With no corporate or personal income tax, Texas has one of the lowest tax burdens in the nation."'),
  ('state_return_nonresident', '{"no_wage_tax": true, "agency": "the Washington Department of Revenue", "quote": "Washington does not currently have an individual income tax.", "summary": {"es": "Según el Washington Department of Revenue, el estado no cobra impuesto a los sueldos, así que por tu sueldo ahí no tendrías declaración estatal. Desde 2028 habrá un impuesto solo para ingresos de más de 1 millón de dólares al año. Confírmalo en la fuente.", "en": "According to the Washington Department of Revenue, the state doesn’t tax wages, so you wouldn’t have a state return for your wages there. Starting in 2028 there will be a tax only on income over 1 million dollars a year. Confirm it at the source."}}'::jsonb, 2026, 'WA', 'https://dor.wa.gov/taxes-rates/income-tax', '2026-10-30', 'pendiente Enrolled Agent', 'Cita textual: "Washington does not currently have an individual income tax."'),
  ('state_return_nonresident', '{"no_wage_tax": true, "agency": "the Wyoming Business Council (state agency, Why Wyoming magazine, Sept. 2025)", "quote": "Businesses and individuals operating in Wyoming are not subject to state income taxes.", "summary": {"es": "Según el Wyoming Business Council (agencia del estado, revista Why Wyoming de sept. 2025), el estado no cobra impuesto a los sueldos, así que por tu sueldo ahí no tendrías declaración estatal. Confírmalo en la fuente.", "en": "According to the Wyoming Business Council (state agency, Why Wyoming magazine, Sept. 2025), the state doesn’t tax wages, so you wouldn’t have a state return for your wages there. Confirm it at the source."}}'::jsonb, 2026, 'WY', 'https://wyomingbusiness.org/wp-content/uploads/2025/09/25_WhyWyoming_Mag_Digital.pdf', '2026-10-30', 'pendiente Enrolled Agent', 'Cita textual: "Businesses and individuals operating in Wyoming are not subject to state income taxes."'),
  ('state_return_due_date', '{"calendar_year": "04-15", "extension": "10-15", "form": "TC-40", "note": "Automatic 6-month extension to file, not to pay; Saturday/Sunday/legal holiday moves to next business day"}'::jsonb, 2026, 'UT', 'https://incometax.utah.gov/general-instructions/', '2026-10-30', 'pendiente Enrolled Agent', 'Utah State Tax Commission, General Instructions (When to File and Pay).')
on conflict (key, jurisdiction, year) do update
  set value = excluded.value, source_url = excluded.source_url, verified_at = excluded.verified_at, notes = excluded.notes;

update public.tax_rules
  set value = value || jsonb_build_object(
        'weekend_holiday_rule_verified', true,
        'weekend_holiday_rule', 'If the regular due date falls on a Saturday, Sunday, or legal holiday, the due date is the next day that is not a Saturday, Sunday, or legal holiday.',
        'weekend_holiday_source', 'https://www.irs.gov/publications/p519'),
      verified_at = '2026-10-30'
  where key = 'form_1040nr_due_date' and jurisdiction = 'federal';
